# Revised rule implementation

def predict_pattern_v2(input_grid):
    gr = len(input_grid)
    gc = len(input_grid[0])

    centers = []
    for r in range(gr):
        for c in range(gc):
            if input_grid[r][c] == 3:
                centers.append((r, c))

    if not centers:
        return [row[:] for row in input_grid]

    output = [[0]*gc for _ in range(gr)]

    for cr, cc in centers:
        # Order matters! We'll apply in a specific order

        dr_top = -2
        dr_bot = +2
        dc_left = -2
        dc_right = +2

        # Step 1: Bottom bar (applied first so it can be overwritten)
        bot_row = cr + dr_bot
        if 0 <= bot_row < gr:
            main_left = cc + dc_left
            main_right = cc + dc_right

            for c in range(max(0, 0), max(0, main_left)):
                output[bot_row][c] = 2

            for c in range(max(0, main_left), min(gc, main_right + 1)):
                output[bot_row][c] = 8

            for c in range(min(gc, main_right + 1), gc):
                output[bot_row][c] = 2

        # Step 2: Top bar with 5
        top_row = cr + dr_top
        if 0 <= top_row < gr:
            left = max(0, cc + dc_left)
            right = min(gc - 1, cc + dc_right)
            for c in range(left, right + 1):
                output[top_row][c] = 5

        # Step 3: Single 5 directly above center (just before center row)
        # This creates the isolated 5 at (cr-1, cc)
        above_center = cr - 1
        if 0 <= above_center < gr:
            output[above_center][cc] = 5

        # Step 4: Center is 3 (overrides everything)
        output[cr][cc] = 3

        # Step 5: Vertical bars with 2 (at cols cc±2, rows cr-1 to cr+1)
        # But don't overwrite existing values that are already set
        for dc in [dc_left, dc_right]:
            col = cc + dc
            if 0 <= col < gc:
                for dr in [-1, 0, 1]:
                    row = cr + dr
                    if 0 <= row < gr:
                        # Only fill if empty
                        if output[row][col] == 0:
                            output[row][col] = 2

    return output

